def additionSite (in_ptr0 in_ptr1 out_ptr : RegionName) (n B : Nat) : Site :=
  .add (Source.prefixBefore (add_kernel in_ptr0 in_ptr1 out_ptr n B).surfaceBody "output") [B]
    (.ref .real [B] "x") (.ref .real [B] "y")

def additionSite (x_ptr output_ptr : RegionName) (N B : Nat) (value : ℝ) : Site :=
  .addScalar (Source.prefixBefore (puzzle1_kernel x_ptr output_ptr N B value).surfaceBody
    "output") B [] (.ref .real [B] "x") (.const value)

def multiplicationSite (in_ptr0 out_ptr : RegionName) (n B : Nat) : Site :=
  .mulScalar (Source.prefixBefore (mul2_kernel in_ptr0 out_ptr n B).surfaceBody
    "output") B [] (.ref .real [B] "x") (.const 2)

def inplaceMultiplicationSite (ptr : RegionName) (n B : Nat) : Site :=
  .mulScalar (Source.prefixBefore (mul2_inplace_kernel ptr n B).surfaceBody
    "output") B [] (.ref .real [B] "x") (.const 2)

def multiplicationSite (in_ptr0 out_ptr : RegionName) (n B : Nat) : Site :=
  .mulScalar (Source.prefixBefore (mul2_kernel in_ptr0 out_ptr n B).surfaceBody
    "output") B [] (.ref .real [B] "x") (.const 2)

def inplaceMultiplicationSite (ptr : RegionName) (n B : Nat) : Site :=
  .mulScalar (Source.prefixBefore (mul2_inplace_kernel ptr n B).surfaceBody
    "output") B [] (.ref .real [B] "x") (.const 2)

def additionSite (x_ptr y_ptr output_ptr : RegionName) (n B : Nat) : Site :=
  .add (Source.prefixBefore (add_kernel x_ptr y_ptr output_ptr n B).surfaceBody "output") [B]
    (.ref .real [B] "x") (.ref .real [B] "y")

def additionSite (A B C : RegionName) (size BLOCK : Nat) : Site :=
  .add (Source.prefixBeforeStore (_add_kernel A B C size BLOCK).surfaceBody) [BLOCK]
    (.ref .real [BLOCK] "a") (.ref .real [BLOCK] "b")
